/**
 * Check if a given object implements the StockExchange interface.
 */
export function instanceOfStockExchange(value) {
    return true;
}
export function StockExchangeFromJSON(json) {
    return StockExchangeFromJSONTyped(json, false);
}
export function StockExchangeFromJSONTyped(json, ignoreDiscriminator) {
    if (json == null) {
        return json;
    }
    return {
        country: json["country"] == null ? undefined : json["country"],
        name: json["name"] == null ? undefined : json["name"],
    };
}
export function StockExchangeToJSON(json) {
    return StockExchangeToJSONTyped(json, false);
}
export function StockExchangeToJSONTyped(value, ignoreDiscriminator = false) {
    if (value == null) {
        return value;
    }
    return {
        country: value["country"],
        name: value["name"],
    };
}
